                    if len(uni) < len(temp[1:]) + len(temp3):
                        temp1 = list(set(temp[1:]) | set(temp3))
                        temp = [temp[0]] + temp1 
                        ls.append(s)
                temp0 = temp[1:]
                temp0.sort()
                temp = [temp[0]]+temp0
                res.append(temp)
            return res
        merged = merge(accounts)
        while merge(merged) != merged:
